alter table proposals drop constraint if exists proposals_status_check;
alter table proposals add constraint proposals_status_check check(status in('draft','sent','accepted','archived'));
alter table proposals add column if not exists sent_at timestamptz,add column if not exists accepted_at timestamptz,add column if not exists locked_at timestamptz,add column if not exists active_revision_id uuid;
create table if not exists proposal_revisions(id uuid primary key default gen_random_uuid(),proposal_id uuid not null references proposals(id),revision_number integer not null,status text not null check(status in('sent','accepted')),snapshot jsonb not null,pdf_storage_path text,created_by text not null,created_at timestamptz not null default now(),locked_at timestamptz not null default now(),unique(proposal_id,revision_number));
alter table proposals add constraint proposals_active_revision_fk foreign key(active_revision_id) references proposal_revisions(id) on delete restrict;
create table if not exists proposal_access_tokens(id uuid primary key default gen_random_uuid(),proposal_id uuid not null references proposals(id),proposal_revision integer not null,revision_id uuid not null references proposal_revisions(id),token_hash text not null unique check(length(token_hash)=64),expires_at timestamptz not null,revoked_at timestamptz,consumed_at timestamptz,first_viewed_at timestamptz,last_viewed_at timestamptz,created_by text not null,created_at timestamptz not null default now());
create table if not exists proposal_acceptances(id uuid primary key default gen_random_uuid(),proposal_id uuid not null references proposals(id),proposal_revision integer not null,revision_id uuid not null references proposal_revisions(id),access_token_id uuid not null references proposal_access_tokens(id),signer_legal_name text not null,signer_email text not null,signature_type text not null check(signature_type in('typed','drawn')),signature_storage_path text,signature_data text not null,selected_option_id text not null,selected_option_snapshot jsonb not null,selected_product text not null,selected_colour text not null,subtotal numeric not null,gst numeric not null,total numeric not null,acknowledgement_data jsonb not null,accepted_at timestamptz not null,request_ip_hash text,user_agent text,integrity_hash text not null,signed_pdf_storage_path text,created_at timestamptz not null default now(),unique(proposal_id,proposal_revision),unique(access_token_id));
create table if not exists proposal_events(id uuid primary key default gen_random_uuid(),proposal_id uuid not null references proposals(id),proposal_revision integer,event_type text not null check(event_type in('sent','send_failed','opened','option_selected','signing_started','accepted','acceptance_failed','signed_pdf_generated','customer_confirmation_sent','internal_notification_sent','token_expired','token_revoked')),actor_type text not null check(actor_type in('admin','customer','system')),metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists proposal_deliveries(id uuid primary key default gen_random_uuid(),proposal_id uuid not null references proposals(id),proposal_revision integer not null,recipient text not null,cc_recipients text[] not null default '{}',sender text not null,subject text not null,message text not null,status text not null,provider_message_id text,error_message text,sent_at timestamptz,created_at timestamptz not null default now());
create index if not exists proposal_tokens_lookup_idx on proposal_access_tokens(token_hash);create index if not exists proposal_events_timeline_idx on proposal_events(proposal_id,created_at);create index if not exists proposal_revisions_lookup_idx on proposal_revisions(proposal_id,revision_number);
do $$declare t text;begin foreach t in array array['proposal_revisions','proposal_access_tokens','proposal_acceptances','proposal_events','proposal_deliveries']loop execute format('alter table %I enable row level security',t);execute format('create policy "proposal signing service role only" on %I for all using(auth.role()=''service_role'') with check(auth.role()=''service_role'')',t);end loop;end$$;
create or replace function accept_proposal_revision(p_token_id uuid,p_proposal_id uuid,p_revision_id uuid,p_revision integer,p_signer_name text,p_signer_email text,p_signature_type text,p_signature_data text,p_selected_id text,p_selected_snapshot jsonb,p_product text,p_colour text,p_subtotal numeric,p_gst numeric,p_total numeric,p_ack jsonb,p_accepted_at timestamptz,p_ip_hash text,p_user_agent text,p_integrity text) returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin perform 1 from proposal_access_tokens where id=p_token_id and proposal_id=p_proposal_id and revision_id=p_revision_id and revoked_at is null and expires_at>now() for update;if not found then raise exception 'token unavailable';end if;perform 1 from proposals where id=p_proposal_id and status='sent' and active_revision_id=p_revision_id for update;if not found then raise exception 'proposal unavailable';end if;insert into proposal_acceptances(proposal_id,proposal_revision,revision_id,access_token_id,signer_legal_name,signer_email,signature_type,signature_data,selected_option_id,selected_option_snapshot,selected_product,selected_colour,subtotal,gst,total,acknowledgement_data,accepted_at,request_ip_hash,user_agent,integrity_hash)values(p_proposal_id,p_revision,p_revision_id,p_token_id,p_signer_name,p_signer_email,p_signature_type,p_signature_data,p_selected_id,p_selected_snapshot,p_product,p_colour,p_subtotal,p_gst,p_total,p_ack,p_accepted_at,p_ip_hash,p_user_agent,p_integrity)returning id into v_id;update proposal_access_tokens set consumed_at=now() where id=p_token_id;update proposal_revisions set status='accepted' where id=p_revision_id;update proposals set status='accepted',accepted_at=p_accepted_at,locked_at=now() where id=p_proposal_id;insert into proposal_events(proposal_id,proposal_revision,event_type,actor_type,metadata)values(p_proposal_id,p_revision,'accepted','customer',jsonb_build_object('acceptance_id',v_id));return v_id;end$$;
revoke all on function accept_proposal_revision(uuid,uuid,uuid,integer,text,text,text,text,text,jsonb,text,text,numeric,numeric,numeric,jsonb,timestamptz,text,text,text) from public,anon,authenticated;
grant execute on function accept_proposal_revision(uuid,uuid,uuid,integer,text,text,text,text,text,jsonb,text,text,numeric,numeric,numeric,jsonb,timestamptz,text,text,text) to service_role;
